using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;
using Microsoft.Win32;
namespace ArchiveReader;
public partial class BooksWindow:Window
{
 readonly string? page;readonly JsonObject options;readonly Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker;CancellationTokenSource? work;bool busy,closing;string? book;JsonArray items=new(),columns=new();JsonArray? taskRect;
 public string? SelectedPageId{get;private set;}
 public string? SelectedRecordId{get;private set;}
 static string T(string s)=>Localizer.Text(s);
 Task<JsonNode> Call(string c,JsonObject? a=null)=>worker(c,a,work?.Token??default);
 public BooksWindow(string? page,JsonObject options,Func<string,JsonObject?,CancellationToken,Task<JsonNode>> worker){this.page=page;this.options=options;this.worker=worker;InitializeComponent();ModelA.Text=options["model"]?.ToString()??"";Loaded+=async(_,_)=>await Run(async()=>{Localizer.Apply(this,Localizer.Language);await LoadBooks();if(Books.Items.Count>0){Books.SelectedIndex=0;await LoadBook();}await LoadTasks();if(Environment.GetCommandLineArgs().Contains("--smoke-roadmap")){if(Books.Items.Count>0){Books.SelectedIndex=0;await LoadBook();}Tabs.IsEnabled=true;for(int i=0;i<Tabs.Items.Count;i++){Tabs.SelectedIndex=i;SmokeCapture.Save(this,"books-ui",$"tab-{i}.png");}closing=true;Close();}});Closing+=(_,e)=>{if(busy&&!closing){e.Cancel=true;closing=true;work?.Cancel();}};}
 async Task Run(Func<Task> f){if(busy)return;busy=true;work=new();Tabs.IsEnabled=false;try{await f();}catch(OperationCanceledException){Status.Text=T("Обробку зупинено. Збережені результати залишилися в бібліотеці.");}catch(Exception ex){Status.Text=T(ex.Message);SmokeCapture.Fail(ex);}finally{Tabs.IsEnabled=true;work.Dispose();work=null;busy=false;if(closing)_=Dispatcher.BeginInvoke(new Action(Close));}}
 void Stop(object s,RoutedEventArgs e)=>work?.Cancel();
 async Task LoadBooks(){Books.ItemsSource=(await Call("books")).AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["name"]+" · "+n["count"])).ToList();if(ColumnField.Items.Count==0){foreach(var pair in new[]{("number","Номер"),("date","Дата"),("person","Особа"),("related1","Батько / чоловік / родич"),("related2","Мати / дружина / родич"),("age","Вік"),("cause","Причина"),("notes","Примітки"),("place","Населений пункт"),("house","Номер будинку"),("text","Текст")})ColumnField.Items.Add(new ComboBoxItem{Content=T(pair.Item2),Tag=pair.Item1});}}
 async Task LoadBook(){if(Books.SelectedItem is not GenealogyRow row)return;book=row.Data["id"]!.ToString();var result=await Call("book_get",new(){["book"]=book});BookName.Text=result["name"]!.ToString();items=result["items"]!.DeepClone().AsArray();RefreshItems();await LoadColumns();await CoverageReport();}
 async void SelectBook(object s,SelectionChangedEventArgs e){if(!busy)await Run(LoadBook);}
 void RefreshItems(){Items.ItemsSource=items.Select((n,i)=>new GenealogyRow(n!.AsObject(),$"{i+1}. {n["label"]} · {n["source"]} · {n["source_number"]}"+(n["page"]==null?" · "+T("Пропущено"):""))).ToList();}
 async Task Save(){var r=await Call("book_save",new(){["book"]=book,["name"]=BookName.Text,["items"]=items.DeepClone()});book=r["id"]!.ToString();items=r["items"]!.DeepClone().AsArray();RefreshItems();await LoadBooks();Books.SelectedItem=Books.Items.Cast<GenealogyRow>().FirstOrDefault(r=>r.Data["id"]!.ToString()==book);await CoverageReport();await LoadColumns();Status.Text=T("Збережено");}
 async void SaveBook(object s,RoutedEventArgs e)=>await Run(Save);
 async void ImportFolder(object s,RoutedEventArgs e){var d=new OpenFolderDialog();if(d.ShowDialog()!=true)return;await Run(async()=>{var r=await Call("book_import_folder",new(){["path"]=d.FolderName});await LoadBooks();Books.SelectedItem=Books.Items.Cast<GenealogyRow>().First(rw=>rw.Data["id"]!.ToString()==r["id"]!.ToString());await LoadBook();Status.Text=T("Помилки імпорту")+": "+r["failures"]!.AsArray().Count;});}
 async void NewBook(object s,RoutedEventArgs e)=>await Run(async()=>{var all=(await Call("list_pages")).AsArray();var selection=new ListBox{DisplayMemberPath="Label",SelectionMode=SelectionMode.Extended,ItemsSource=all.Select(n=>new GenealogyRow(n!.AsObject(),n["label"]!.ToString())).ToList()};var panel=new DockPanel();var add=new Button{Content=T("Додати вибрані сторінки"),Height=40};DockPanel.SetDock(add,Dock.Bottom);panel.Children.Add(add);panel.Children.Add(selection);var dialog=new Window{Owner=this,Title=T("Нова книга з вибраних сторінок"),Width=850,Height=600,Content=panel};add.Click+=(_,_)=>dialog.DialogResult=true;if(dialog.ShowDialog()!=true)return;book=null;BookName.Text=T("Нова книга");items=new JsonArray(selection.SelectedItems.Cast<GenealogyRow>().Select(r=>(JsonNode)new JsonObject{["page"]=r.Data["id"]!.ToString(),["label"]=r.Data["name"]!.ToString()}).ToArray());RefreshItems();});
 void Move(int delta){int i=Items.SelectedIndex,j=i+delta;if(i<0||j<0||j>=items.Count)return;var n=items[i];items.RemoveAt(i);items.Insert(j,n);RefreshItems();Items.SelectedIndex=j;}
 void MoveUp(object s,RoutedEventArgs e)=>Move(-1);void MoveDown(object s,RoutedEventArgs e)=>Move(1);
 void RemovePage(object s,RoutedEventArgs e){if(Items.SelectedIndex<0)return;items.RemoveAt(Items.SelectedIndex);RefreshItems();}
 void AddGap(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(Folio.Text))return;items.Insert(Items.SelectedIndex<0?items.Count:Items.SelectedIndex+1,new JsonObject{["label"]=Folio.Text});RefreshItems();}
 void RenamePage(object s,RoutedEventArgs e){if(Items.SelectedIndex<0)return;items[Items.SelectedIndex]!["label"]=Folio.Text;RefreshItems();}
 void Go(string? id){if(id==null)return;SelectedPageId=id;DialogResult=true;}
 void OpenPage(object s,RoutedEventArgs e)=>Go((Items.SelectedItem as GenealogyRow)?.Data["page"]?.ToString());
 async Task CoverageReport(){if(book==null)return;var r=await Call("book_index",new(){["book"]=book});Coverage.Text=T("Сторінки")+": "+r["pages"]+"\n"+T("Готово")+": "+r["recognized"]+"\n"+T("Пропуски")+": "+r["gaps"]+"\n"+T("Помилка")+": "+r["errors"]!.AsArray().Count;}
 async void IndexBook(object s,RoutedEventArgs e)=>await Run(async()=>{await Save();var r=await Call("book_index",new(){["book"]=book});int i=0;foreach(var id in r["pending"]!.AsArray()){work!.Token.ThrowIfCancellationRequested();var args=options.DeepClone().AsObject();args["id"]=id!.ToString();if(ReadImages.IsChecked==true)args["useTextLayer"]=false;Status.Text=T("Індексація книги")+$" · {++i}/{r["pending"]!.AsArray().Count}";try{await Call("recognize",args);}catch(OperationCanceledException){throw;}catch(Exception ex){Status.Text=T(ex.Message);}await CoverageReport();}await CoverageReport();Status.Text=T("Чергу завершено. Перевірте помилки й результати.");});
 async void ExportPdf(object s,RoutedEventArgs e){var d=new SaveFileDialog{Filter="PDF|*.pdf",FileName=string.Concat(BookName.Text.Select(c=>System.IO.Path.GetInvalidFileNameChars().Contains(c)?'_':c))+".pdf"};if(d.ShowDialog()!=true)return;await Run(async()=>{await Save();var r=await Call("book_pdf",new(){["book"]=book,["path"]=d.FileName});Status.Text=T("Експорт завершено")+"\n"+r["path"]+"\n"+T("Звіт")+": "+r["report"];});}
 async void Search(object s,RoutedEventArgs e)=>await Run(async()=>{if(CurrentBookOnly.IsChecked==true&&book==null)throw new Exception(T("Спочатку виберіть книгу."));var r=await Call("record_search",new(){["book"]=CurrentBookOnly.IsChecked==true?book:null,["person"]=Person.Text,["place"]=Place.Text,["house"]=House.Text,["year_from"]=YearFrom.Text,["year_to"]=YearTo.Text});SearchRows.ItemsSource=r["rows"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),$"{n["data"]!["person"]} · {n["data"]!["date"]} · {n["data"]!["place"]} · {n["data"]!["house"]} · {n["name"]} · {n["number"]}")).ToList();Status.Text=T("Знайдено")+": "+r["rows"]!.AsArray().Count+(r["limited"]!.GetValue<bool>()?" · "+T("Уточніть пошук"):"");});
 void OpenSearch(object s,RoutedEventArgs e){if(SearchRows.SelectedItem is not GenealogyRow row)return;SelectedRecordId=row.Data["data"]!=null?row.Data["id"]?.ToString():row.Data["source"]?.ToString()=="record"?row.Data["entity"]?.ToString():null;Go(row.Data["page"]?.ToString());}
 void OpenTaskPage(object s,RoutedEventArgs e)=>Go((Tasks.SelectedItem as GenealogyRow)?.Data["page"]?.ToString());
 async void SearchText(object s,RoutedEventArgs e)=>await Run(async()=>{if(CurrentBookOnly.IsChecked==true&&book==null)throw new Exception(T("Спочатку виберіть книгу."));var r=await Call("library_search",new(){["query"]=TextQuery.Text,["book"]=CurrentBookOnly.IsChecked==true?book:null});SearchRows.ItemsSource=r["rows"]!.AsArray().Select(n=>new GenealogyRow(n!.AsObject(),n["name"]+" · "+n["number"]+" · "+n["snippet"])).ToList();Status.Text=T("Знайдено")+": "+r["rows"]!.AsArray().Count;});
 async Task LoadTasks(){Tasks.ItemsSource=(await Call("research_task",new(){["open_only"]=OpenTasksOnly.IsChecked==true})).AsArray().Select(n=>new GenealogyRow(n!.AsObject(),$"{n["name"]} · {n["number"]} · {n["data"]!["text"]}"+(n["data"]!["done"]?.GetValue<bool>()==true?" · "+T("Готово"):""))).ToList();}
 async void RefreshTasks(object s,RoutedEventArgs e)=>await Run(LoadTasks);
 void TaskPreset(object s,RoutedEventArgs e)=>TaskText.Text=((Button)s).Content.ToString();
 async void TaskRegion(object s,RoutedEventArgs e)=>await Run(async()=>{if(page==null)return;var r=await Call("render",new(){["id"]=page,["whole"]=true});var picker=new RegionPicker(r["path"]!.ToString()){Owner=this};if(picker.ShowDialog()==true){taskRect=picker.Bounds;TaskRegionLabel.Text=T("Фрагмент вибрано");}});
 async void AddTask(object s,RoutedEventArgs e)=>await Run(async()=>{if(page==null)return;await Call("research_task",new(){["page"]=page,["data"]=new JsonObject{["text"]=TaskText.Text,["rect"]=taskRect?.DeepClone(),["done"]=false}});await LoadTasks();});
 async void ToggleTask(object s,RoutedEventArgs e)=>await Run(async()=>{if(Tasks.SelectedItem is not GenealogyRow row)return;var data=row.Data["data"]!.DeepClone().AsObject();data["done"]=!(data["done"]?.GetValue<bool>()??false);await Call("research_task",new(){["id"]=row.Data["id"]!.ToString(),["page"]=row.Data["page"]!.ToString(),["data"]=data});await LoadTasks();});
 async void OpenTask(object s,RoutedEventArgs e)=>await Run(async()=>{if(Tasks.SelectedItem is not GenealogyRow row)return;var r=await Call("render",new(){["id"]=row.Data["page"]!.ToString(),["whole"]=true});var bitmap=new BitmapImage(new Uri(r["path"]!.ToString()));System.Windows.Media.ImageSource source=bitmap;if(row.Data["data"]!["rect"] is JsonArray rect){int x=(int)(rect[0]!.GetValue<double>()*bitmap.PixelWidth),y=(int)(rect[1]!.GetValue<double>()*bitmap.PixelHeight);source=new CroppedBitmap(bitmap,new Int32Rect(x,y,Math.Min(bitmap.PixelWidth-x,Math.Max(1,(int)(rect[2]!.GetValue<double>()*bitmap.PixelWidth))),Math.Min(bitmap.PixelHeight-y,Math.Max(1,(int)(rect[3]!.GetValue<double>()*bitmap.PixelHeight)))));}new Window{Owner=this,Title=row.Data["data"]!["text"]!.ToString(),Width=950,Height=700,Content=new ScrollViewer{Content=new Image{Source=source}}}.ShowDialog();});
 async Task LoadColumns(){if(book==null)return;columns=(await Call("book_template",new(){["book"]=book})).AsArray();Columns.ItemsSource=columns.Select(n=>new GenealogyRow(n!.AsObject(),n["label"]+" · "+n["field"]+" · "+n["meaning"])).ToList();}
 async void CaptureTemplate(object s,RoutedEventArgs e)=>await Run(async()=>{if(page==null)return;await Save();var a=(await Call("annotations",new(){["id"]=page})).AsArray();var cols=new JsonArray(a.Where(n=>n!["kind"]!.ToString()=="column").Select(n=>n!.DeepClone()).ToArray());if(cols.Count==0)throw new Exception(T("Спочатку розмітьте колонки сторінки."));await Call("book_template",new(){["book"]=book,["columns"]=cols});await LoadColumns();});
 void SelectColumn(object s,SelectionChangedEventArgs e){if(Columns.SelectedItem is not GenealogyRow row)return;ColumnMeaning.Text=row.Data["meaning"]?.ToString()??"";ColumnLabel.Text=row.Data["label"]?.ToString()??"";ColumnField.SelectedItem=ColumnField.Items.Cast<ComboBoxItem>().FirstOrDefault(i=>i.Tag.ToString()==row.Data["field"]?.ToString());}
 async void SaveMeaning(object s,RoutedEventArgs e)=>await Run(async()=>{if(Columns.SelectedIndex<0||book==null)return;columns[Columns.SelectedIndex]!["meaning"]=ColumnMeaning.Text;columns[Columns.SelectedIndex]!["label"]=ColumnLabel.Text;columns[Columns.SelectedIndex]!["field"]=(ColumnField.SelectedItem as ComboBoxItem)?.Tag.ToString()??"text";await Call("book_template",new(){["book"]=book,["columns"]=columns.DeepClone()});await LoadColumns();});
 async void ApplyTemplate(object s,RoutedEventArgs e)=>await Run(async()=>{if(book==null)return;var r=await Call("book_template",new(){["book"]=book,["apply"]=true});Status.Text=T("Додано колонок")+": "+r["added"]+" · "+T("Пропущено сторінок")+": "+r["skipped"];});
 async void Freeze(object s,RoutedEventArgs e)=>await Run(async()=>{var r=await Call("benchmark_freeze");FrozenPath.Text=r["path"]!.ToString();});
 void ChooseFrozen(object s,RoutedEventArgs e){var d=new OpenFolderDialog();if(d.ShowDialog()==true)FrozenPath.Text=d.FolderName;}
 void ChooseModel(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="Kraken|*.mlmodel;*.safetensors"};if(d.ShowDialog()==true){if(((Button)s).Tag.ToString()=="A")ModelA.Text=d.FileName;else ModelB.Text=d.FileName;}}
 static string Percent(JsonNode? value)=>value==null?"—":value.GetValue<double>().ToString("P1");
 async void Compare(object s,RoutedEventArgs e)=>await Run(async()=>{if(string.IsNullOrWhiteSpace(ModelA.Text)||string.IsNullOrWhiteSpace(ModelB.Text)||System.IO.Path.GetFullPath(ModelA.Text).Equals(System.IO.Path.GetFullPath(ModelB.Text),StringComparison.OrdinalIgnoreCase))throw new Exception(T("Для порівняння виберіть різні моделі."));var models=new JsonArray(new JsonObject{["name"]="A",["engine"]="kraken",["path"]=ModelA.Text},new JsonObject{["name"]="B",["engine"]="kraken",["path"]=ModelB.Text});var r=await Call("benchmark_compare",new(){["path"]=FrozenPath.Text,["models"]=models});var report=string.Join("\n",r["models"]!.AsArray().Select(m=>$"{m!["name"]}: CER {Percent(m["micro_cer"])}, WER {Percent(m["micro_wer"])} · "+T("Готово")+": "+m["scored_lines"]+" · "+T("Помилка")+": "+m["failed_lines"]+" · "+T("Секунди з завантаженням моделі")+": "+m["seconds_including_model_load"]));foreach(var b in r["by_book"]!.AsArray()){report+="\n\n"+b!["name"]+" · "+T("Спільні перевірені рядки")+": "+b["common_scored_lines"]+" / "+b["lines"];foreach(var m in b["models"]!.AsArray())report+=$"\n{m!["name"]}: CER {Percent(m["common_cer"])}, WER {Percent(m["common_wer"])} · "+T("Помилка")+": "+m["failed_lines"];}ComparisonReport.Text=report+"\n\n"+T("Звіт")+": "+r["path"];});
}
